SELECT p.id, p.title, p.cover_image, p.content_text, p.like_count, p.comment_count, p.collect_count, p.created_at, u.id AS author_id, u.username AS author_username, u.nickname AS author_nickname, u.avatar AS author_avatar, IF(lk.id IS NOT NULL, TRUE, FALSE) AS is_liked, IF(fav.id IS NOT NULL, TRUE, FALSE) AS is_collected FROM post p JOIN user u ON p.user_id = u.id LEFT JOIN user_like lk ON lk.target_id = p.id AND lk.target_type = 1 AND lk.user_id = #{userId} LEFT JOIN user_favorite fav ON fav.post_id = p.id AND fav.user_id = #{userId} WHERE p.status = 1
AND (p.created_at < #{cursorTime} OR (p.created_at = #{cursorTime} AND p.id < #{cursorId}))
ORDER BY p.created_at DESC, p.id DESC LIMIT #{size}

SELECT p.id, p.title, p.cover_image, p.content_text,
       p.like_count, p.comment_count, p.collect_count, p.created_at,
       u.id AS author_id, u.username AS author_username,
       u.nickname AS author_nickname, u.avatar AS author_avatar,
       IF(lk.id IS NOT NULL, TRUE, FALSE) AS is_liked,
       IF(fav.id IS NOT NULL, TRUE, FALSE) AS is_collected
FROM post p
JOIN user u ON p.user_id = u.id
LEFT JOIN user_like lk ON lk.target_id = p.id AND lk.target_type = 1 AND lk.user_id = #{userId}
LEFT JOIN user_favorite fav ON fav.post_id = p.id AND fav.user_id = #{userId}
WHERE p.status = 1 AND p.user_id = #{targetUserId}

    AND (p.created_at < #{cursorTime}
         OR (p.created_at = #{cursorTime} AND p.id < #{cursorId}))

ORDER BY p.created_at DESC, p.id DESC
LIMIT #{size}

